declarations:
static class Gruppen {
    private final int[] parent;
    Gruppen(int n) {
        parent = new int[n];
        for (int i = 0; i < n; i++) parent[i] = i;
    }
    int find(int x) {
        Objects.checkIndex(x, parent.length);
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }
    void union(int a, int b) { parent[find(a)] = find(b); }
}

